//! rtg.library's functions for drivers: what a display's or a bus's
//! driver calls, as the library's second interface. The base is the one
//! OpenLibrary("rtg.library", 1) answers, seen as an RtgDriverBase; its
//! slots follow those of the programs' interface, sdk/fd/rtg_lib.fd, in
//! the one jump table.
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/rtgdriver_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const utility = @import("../libs/utility/utility.zig");
const rtg = @import("../libs/rtg/rtg.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "rtg.library";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const AddRtgDriver = libraries.lvo(61);
    pub const RemRtgDriver = libraries.lvo(62);
    pub const FrameDone = libraries.lvo(63);
    pub const TxParam = libraries.lvo(64);
    pub const TxColor = libraries.lvo(65);
    pub const RxParam = libraries.lvo(66);
    pub const GetRtgTagData = libraries.lvo(67);
    pub const CreateBoard = libraries.lvo(68);
    pub const DeleteBoard = libraries.lvo(69);
    pub const AddRtgDevice = libraries.lvo(70);
    pub const RemRtgDevice = libraries.lvo(71);
    pub const OpenTransport = libraries.lvo(72);
    pub const CloseTransport = libraries.lvo(73);
    pub const AddBoardMode = libraries.lvo(74);
    pub const ReadTimingTags = libraries.lvo(75);
    pub const MonitorChanged = libraries.lvo(76);
    pub const FindStandardTimings = libraries.lvo(77);
    pub const ComposeLines = libraries.lvo(78);
    pub const BuildAviInfoFrame = libraries.lvo(79);
    pub const HdmiAudioClock = libraries.lvo(80);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const AddRtgDriver = *const fn (*RtgDriverBase, *const rtg.RtgDriverSpec, ?*anyopaque) callconv(.c) ?*rtg.RtgDriver;
    pub const RemRtgDriver = *const fn (*RtgDriverBase, *rtg.RtgDriver) callconv(.c) bool;
    pub const FrameDone = *const fn (*RtgDriverBase, *rtg.RtgBoard) callconv(.c) void;
    pub const TxParam = *const fn (*RtgDriverBase, *rtg.RtgTransport, i32, ?*const anyopaque, u32) callconv(.c) i32;
    pub const TxColor = *const fn (*RtgDriverBase, *rtg.RtgTransport, i32, ?*const anyopaque, u32) callconv(.c) i32;
    pub const RxParam = *const fn (*RtgDriverBase, *rtg.RtgTransport, i32, ?*anyopaque, u32) callconv(.c) i32;
    pub const GetRtgTagData = *const fn (*RtgDriverBase, utility.Tag, usize, ?[*]const utility.TagItem) callconv(.c) usize;
    pub const CreateBoard = *const fn (*RtgDriverBase, *rtg.RtgDriver, *rtg.RtgDevice, *const rtg.RtgBoardSpec) callconv(.c) ?*rtg.RtgBoard;
    pub const DeleteBoard = *const fn (*RtgDriverBase, ?*rtg.RtgBoard) callconv(.c) void;
    pub const AddRtgDevice = *const fn (*RtgDriverBase, ?[*]const utility.TagItem) callconv(.c) ?*rtg.RtgDevice;
    pub const RemRtgDevice = *const fn (*RtgDriverBase, ?*rtg.RtgDevice) callconv(.c) void;
    pub const OpenTransport = *const fn (*RtgDriverBase, *rtg.RtgDriver, *rtg.RtgDevice) callconv(.c) ?*rtg.RtgTransport;
    pub const CloseTransport = *const fn (*RtgDriverBase, ?*rtg.RtgTransport) callconv(.c) void;
    pub const AddBoardMode = *const fn (*RtgDriverBase, *rtg.RtgBoard, *const rtg.RtgTimings, u32, u32) callconv(.c) u32;
    pub const ReadTimingTags = *const fn (*RtgDriverBase, ?[*]const utility.TagItem, *rtg.RtgTimings) callconv(.c) bool;
    pub const MonitorChanged = *const fn (*RtgDriverBase, *rtg.RtgBoard) callconv(.c) void;
    pub const FindStandardTimings = *const fn (*RtgDriverBase, u32, u32, u32, *rtg.RtgTimings) callconv(.c) bool;
    pub const ComposeLines = *const fn (*RtgDriverBase, *rtg.RtgBoard, *const rtg.RtgRect, [*]u8, u32) callconv(.c) i32;
    pub const BuildAviInfoFrame = *const fn (*RtgDriverBase, *const rtg.RtgTimings, u32, [*]u8) callconv(.c) u32;
    pub const HdmiAudioClock = *const fn (*RtgDriverBase, u32, u32, *u32, *u32) callconv(.c) bool;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const RtgDriverBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *RtgDriverBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// Put a driver's description on the list: the library makes the
    /// driver's node, with the state the description asks for behind it,
    /// cleared. `seg_list` is the segments of a driver that was loaded, null
    /// for one in ROM. Null for a name already there, for ops that fill in
    /// neither create, or without memory. Not from interrupts.
    pub fn AddRtgDriver(self: *RtgDriverBase, spec: *const rtg.RtgDriverSpec, seg_list: ?*anyopaque) ?*rtg.RtgDriver {
        return libraries.call(self, LVO.AddRtgDriver, Fn.AddRtgDriver, .{ spec, seg_list });
    }

    /// Take a driver off the list and free its node and its state. False
    /// while a board or a bus it made is still alive, and for one that is not
    /// on the list. Not from interrupts.
    pub fn RemRtgDriver(self: *RtgDriverBase, driver: *rtg.RtgDriver) bool {
        return libraries.call(self, LVO.RemRtgDriver, Fn.RemRtgDriver, .{driver});
    }

    /// A frame of the board's display ended: counted, and whoever waits for
    /// it (WaitVBlank) woken. A driver calls it from its frame interrupt.
    pub fn FrameDone(self: *RtgDriverBase, board: *rtg.RtgBoard) void {
        return libraries.call(self, LVO.FrameDone, Fn.FrameDone, .{board});
    }

    /// A command and its parameters to the part. A command below zero sends
    /// the parameters alone.
    pub fn TxParam(self: *RtgDriverBase, io: *rtg.RtgTransport, cmd: i32, param: ?*const anyopaque, size: u32) i32 {
        return libraries.call(self, LVO.TxParam, Fn.TxParam, .{ io, cmd, param, size });
    }

    /// A command and a run of pixels. It comes back when the bytes have gone.
    pub fn TxColor(self: *RtgDriverBase, io: *rtg.RtgTransport, cmd: i32, color: ?*const anyopaque, size: u32) i32 {
        return libraries.call(self, LVO.TxColor, Fn.TxColor, .{ io, cmd, color, size });
    }

    /// Send a command and read `size` bytes back, with nothing else reaching
    /// the bus in between.
    pub fn RxParam(self: *RtgDriverBase, io: *rtg.RtgTransport, cmd: i32, buffer: ?*anyopaque, size: u32) i32 {
        return libraries.call(self, LVO.RxParam, Fn.RxParam, .{ io, cmd, buffer, size });
    }

    /// A tag's data, or `default_value` if it is not in the list. Here so a
    /// driver need open nothing but this library.
    pub fn GetRtgTagData(self: *RtgDriverBase, tag_value: utility.Tag, default_value: usize, tag_list: ?[*]const utility.TagItem) usize {
        return libraries.call(self, LVO.GetRtgTagData, Fn.GetRtgTagData, .{ tag_value, default_value, tag_list });
    }

    /// A board for one output of a device, from the driver's attach: the
    /// handle and the instance the description asks for, cleared. It joins
    /// the library's list, named, once the attach has answered RTGERR_OK.
    /// Null: not inside the driver's attach for that device, or no memory.
    pub fn CreateBoard(self: *RtgDriverBase, driver: *rtg.RtgDriver, device: *rtg.RtgDevice, spec: *const rtg.RtgBoardSpec) ?*rtg.RtgBoard {
        return libraries.call(self, LVO.CreateBoard, Fn.CreateBoard, .{ driver, device, spec });
    }

    /// Give a board back: for an attach that fails after making one, and for
    /// a driver that is being removed. Refused while a task waits for a
    /// frame of it or a video layer is still on it. Null does nothing.
    pub fn DeleteBoard(self: *RtgDriverBase, board: ?*rtg.RtgBoard) void {
        return libraries.call(self, LVO.DeleteBoard, Fn.DeleteBoard, .{board});
    }

    /// A device the library cannot find by itself, made from tags that say
    /// what a panel part's say (PART_Chip, PART_Bus, RTGA_*), and offered to
    /// the drivers at once. The tags are read for as long as the device
    /// lives. Null without memory.
    pub fn AddRtgDevice(self: *RtgDriverBase, tag_list: ?[*]const utility.TagItem) ?*rtg.RtgDevice {
        return libraries.call(self, LVO.AddRtgDevice, Fn.AddRtgDevice, .{tag_list});
    }

    /// A device AddRtgDevice made is gone: its boards are marked gone and
    /// stay handles, its driver's detach is called, and the device is freed.
    /// Null does nothing.
    pub fn RemRtgDevice(self: *RtgDriverBase, device: ?*rtg.RtgDevice) void {
        return libraries.call(self, LVO.RemRtgDevice, Fn.RemRtgDevice, .{device});
    }

    /// The bus a device is reached over, made by the transport driver whose
    /// table names the device's bus, from the device's tags. Null: no such
    /// driver, no memory, or a driver that could not make it.
    pub fn OpenTransport(self: *RtgDriverBase, driver: *rtg.RtgDriver, device: *rtg.RtgDevice) ?*rtg.RtgTransport {
        return libraries.call(self, LVO.OpenTransport, Fn.OpenTransport, .{ driver, device });
    }

    /// Give a bus back. Null does nothing.
    pub fn CloseTransport(self: *RtgDriverBase, io: ?*rtg.RtgTransport) void {
        return libraries.call(self, LVO.CloseTransport, Fn.CloseTransport, .{io});
    }

    /// A mode of a board, from its driver: these timings in that pixel
    /// format, with RTGMF_DEFAULT for the one the board comes up in and
    /// RTGMF_TURNED for a picture a quarter turn round. The library names it
    /// and gives it a number, which it answers; 0 for timings with no picture,
    /// a format this build does not know, or no memory. A mode of the same
    /// figures is the one already there.
    pub fn AddBoardMode(self: *RtgDriverBase, board: *rtg.RtgBoard, timings: *const rtg.RtgTimings, format: u32, flags: u32) u32 {
        return libraries.call(self, LVO.AddBoardMode, Fn.AddBoardMode, .{ board, timings, format, flags });
    }

    /// A part's timings - RTGA_Width, RTGA_Height and the block from
    /// RTGA_PixelClock to RTGA_TimingFlags - into `timings`. False for a list
    /// with no size, and for one that names a pixel clock without both sync
    /// pulses; `timings` is then left as it was.
    pub fn ReadTimingTags(self: *RtgDriverBase, tag_list: ?[*]const utility.TagItem, timings: *rtg.RtgTimings) bool {
        return libraries.call(self, LVO.ReadTimingTags, Fn.ReadTimingTags, .{ tag_list, timings });
    }

    /// Something happened at the board's connector: have its `detect` asked
    /// again and its modes made of what the monitor now there names. The
    /// library does that on a task of its own. From an interrupt or a task.
    pub fn MonitorChanged(self: *RtgDriverBase, board: *rtg.RtgBoard) void {
        return libraries.call(self, LVO.MonitorChanged, Fn.MonitorChanged, .{board});
    }

    /// The standard's timings for a picture of that size at that refresh, in
    /// frames a second - CEA-861's, with its number, or VESA's - into
    /// `timings`. False, and `timings` left as it was, where the library
    /// knows none.
    pub fn FindStandardTimings(self: *RtgDriverBase, width: u32, height: u32, refresh_hz: u32, timings: *rtg.RtgTimings) bool {
        return libraries.call(self, LVO.FindStandardTimings, Fn.FindStandardTimings, .{ width, height, refresh_hz, timings });
    }

    /// The pixels of a rectangle of the board's display as they are to be
    /// seen, in the mode's format, into `into`, its rows `pitch` bytes apart:
    /// the bands, and over them the overlay and the pointer where the
    /// library lays them, mirrored where the library mirrors the picture,
    /// and black on a board that is blank or asleep. What a driver whose display has a picture of its
    /// own calls from its `update` and its `show`. RTGERR_BAD_ARG for a
    /// rectangle that is empty or not wholly inside the display,
    /// RTGERR_BAD_FORMAT in a mode whose pixels are not whole bytes.
    pub fn ComposeLines(self: *RtgDriverBase, board: *rtg.RtgBoard, area: *const rtg.RtgRect, into: [*]u8, pitch: u32) i32 {
        return libraries.call(self, LVO.ComposeLines, Fn.ComposeLines, .{ board, area, into, pitch });
    }

    /// The AVI infoframe a link sends with a mode of these timings, into
    /// `into`, RTG_AVI_BYTES of it: its header, its checksum and its bytes -
    /// RGB, the picture's aspect, the mode's number. `flags` (RTGAVI_) say a
    /// computer's picture, the range, and to leave the number out. Answers
    /// the bytes written.
    pub fn BuildAviInfoFrame(self: *RtgDriverBase, timings: *const rtg.RtgTimings, flags: u32, into: [*]u8) u32 {
        return libraries.call(self, LVO.BuildAviInfoFrame, Fn.BuildAviInfoFrame, .{ timings, flags, into });
    }

    /// The two numbers a monitor rebuilds the sample clock of a link's sound
    /// from, N and CTS, for a pixel clock and a sample rate: 128 times the
    /// rate is the pixel clock times N over CTS. False for a rate or a clock
    /// of 0, and nothing is written.
    pub fn HdmiAudioClock(self: *RtgDriverBase, pixel_clock_hz: u32, sample_rate: u32, n: *u32, cts: *u32) bool {
        return libraries.call(self, LVO.HdmiAudioClock, Fn.HdmiAudioClock, .{ pixel_clock_hz, sample_rate, n, cts });
    }
};
